//! R10 closure: live multi-level capacity from native Owner books. Public data, no trading.
use futures_util::{SinkExt,StreamExt};use serde_json::json;use spotarb_native_market_core::{owner_index,HistorySink,CoreError,Owner,RawFrame,Update,Venue};use std::{collections::{HashMap,HashSet},time::{Duration,Instant,SystemTime,UNIX_EPOCH}};use tokio_tungstenite::{connect_async,tungstenite::Message};
struct H{n:u64}impl HistorySink for H{fn accept(&mut self,_:&RawFrame,_:&Update)->Result<(),CoreError>{self.n+=1;Ok(())}}fn wall()->i64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_millis()as i64}fn vw(l:&[(f64,f64)],q:f64)->Option<f64>{let(mut x,mut t)=(q,0.);for&(p,a)in l{let z=x.min(a);t+=z*p;x-=z;if x<=q*1e-9{return Some(t/q)}}None}
#[tokio::main]async fn main(){let bases=std::env::var("R10_BASES").unwrap().split(',').map(str::to_string).collect::<Vec<_>>();let secs=std::env::var("R10_SECONDS").ok().and_then(|s|s.parse().ok()).unwrap_or(60);let start=Instant::now();let mut owners=(0..12).map(|i|Owner::new(i,12,800).unwrap()).collect::<Vec<_>>();let mut h=H{n:0};let(mut sb,mut so)=(HashSet::new(),HashSet::new());let mut errors=0u64;let streams=bases.iter().map(|x|format!("{}usdt@depth20@100ms",x.to_lowercase())).collect::<Vec<_>>().join("/");let(mut b,_)=connect_async(format!("wss://fstream.binance.com/stream?streams={streams}")).await.unwrap();let(mut o,_)=connect_async("wss://ws.okx.com:8443/ws/v5/public").await.unwrap();let args=bases.iter().map(|x|json!({"channel":"books5","instId":format!("{x}-USDT")})).collect::<Vec<_>>();o.send(Message::Text(json!({"op":"subscribe","args":args}).to_string())).await.unwrap();while start.elapsed()<Duration::from_secs(secs){tokio::select!{x=b.next()=>if let Some(Ok(Message::Text(raw)))=x{let f=RawFrame{source:None,venue:Venue::BinanceFutures,epoch:1,received_ns:start.elapsed().as_nanos()as u64,received_wall_ms:wall(),raw};match spotarb_native_market_core::parse(&f){Ok(u)=>{sb.insert(u.base.clone());let i=owner_index(&u.base,12);if owners[i].ingest_parsed(&f,u,&mut h).is_err(){errors+=1}},Err(_)=>errors+=1}},x=o.next()=>if let Some(Ok(Message::Text(raw)))=x{if raw.contains("\"event\""){continue}let f=RawFrame{source:None,venue:Venue::OkxSpot,epoch:1,received_ns:start.elapsed().as_nanos()as u64,received_wall_ms:wall(),raw};match spotarb_native_market_core::parse(&f){Ok(u)=>{so.insert(u.base.clone());let i=owner_index(&u.base,12);if owners[i].ingest_parsed(&f,u,&mut h).is_err(){errors+=1}},Err(_)=>errors+=1}}}}let now=start.elapsed().as_nanos()as u64;let mut reasons:HashMap<&str,u64>=HashMap::new();let mut candidates=vec![];let mut paired=0;for base in &bases{let i=owner_index(base,12);if let(Some(s),Some(f))=owners[i].snapshot_pair(base){paired+=1;if now<s.received_ns||now-s.received_ns>800_000_000||now<f.received_ns||now-f.received_ns>800_000_000{*reasons.entry("STALE_BOOK").or_default()+=1;continue}if s.asks.is_empty()||f.bids.is_empty(){*reasons.entry("SYSTEM_NOT_READY").or_default()+=1;continue}let upper=(f.bids[0].0/s.asks[0].0-1.)*10000.;if upper-20.<42.{*reasons.entry("EDGE_TOO_LOW").or_default()+=1;continue}let price=s.asks[0].0.max(f.bids[0].0);let mut best=0.;let mut rows=vec![];for usd in[10.,25.,50.,100.,200.,500.]{let q=usd/price;match(vw(&s.asks,q),vw(&f.bids,q)){(Some(a),Some(z))=>{let net=(z/a-1.)*10000.-20.;let ok=net>=42.;if ok{best=usd}rows.push(json!({"usd":usd,"net_bps":net,"ok":ok}))},_=>rows.push(json!({"usd":usd,"reason":"DEPTH_DENY"}))}}if best>0.{*reasons.entry("EXECUTABLE_DEPTH_CANDIDATE").or_default()+=1;candidates.push(json!({"base":base,"capacity_ladder_usdt":best,"levels_spot":s.asks.len(),"levels_future":f.bids.len(),"samples":rows}))}else{*reasons.entry("NO_EXECUTABLE_DEPTH").or_default()+=1}}}println!("{}",json!({"r10_depth_capacity_live":errors==0&&paired==bases.len(),"requested":bases.len(),"binance_seen":sb.len(),"okx_seen":so.len(),"paired":paired,"updates":h.n,"errors":errors,"reasons":reasons,"candidates":candidates,"cost_bps":20,"required_net_bps":42,"trading":false}));}